contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address u) public payable {
        uint beforeU = c.getBalance(u); if (__ESBMC_reverted()) return;
        uint beforeC = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterU = c.getBalance(u); if (__ESBMC_reverted()) return;

        assert(reverted || afterU == beforeU);
    }
}

